from fractions import Fraction
from itertools import product


def prob_dice(event, n_dice=2):
    hits = 0
    total = 0
    for roll in product(range(1, 7), repeat=n_dice):
        total += 1
        if event(roll):
            hits += 1
    return Fraction(hits, max(total, 1))


def natural_frequency(base, sens, fpr, n=1000):
    have = n * Fraction(base)
    true_pos = have * Fraction(sens)
    false_pos = (n - have) * Fraction(fpr)
    return true_pos, false_pos, true_pos / (true_pos + false_pos)
